'use client';

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { AdminPageTemplate } from '@/components/admin/layout/AdminPageTemplate';
import { BookingsFilterBar } from '@/components/admin/bookings/BookingsFilterBar';
import { BookingsTable } from '@/components/admin/bookings/BookingsTable';
import { BookingDetailsDrawer } from '@/components/admin/bookings/BookingDetailsDrawer';
import { useBookingSelection } from '@/hooks/admin/useBookingSelection';
import { mockBookings, Booking, BookingStatus } from '@/data/admin/mockBookings';
import { AdminIcon } from '@/components/admin/navigation/AdminIcons';
import { KPICard } from '@/components/admin/layout/KPICard';
import { AdminDialog, DialogFooterCancel, DialogFooterConfirm } from '@/components/admin/overlays/AdminDialog';
import { useToast } from '@/components/admin/feedback/Toast';

export default function BookingsPage() {
  const { selectedBooking, isDrawerOpen, openDrawer, closeDrawer } = useBookingSelection();
  const { success, error } = useToast();
  const [isLoading, setIsLoading] = useState(true);

  // Pagination state
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(10);

  // Filter state
  const [activeTab, setActiveTab] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');

  // Cancel dialog state
  const [cancelTarget, setCancelTarget] = useState<Booking | null>(null);

  // Simulate network latency for skeleton testing
  useEffect(() => {
    const timer = setTimeout(() => {
      setIsLoading(false);
    }, 800);
    return () => clearTimeout(timer);
  }, []);

  // Filter data based on active tab and search
  const filteredBookings = useMemo(() => {
    let result = [...mockBookings];

    // Tab filtering
    switch (activeTab) {
      case 'pending':
        result = result.filter(b => b.status === 'Pending' || b.status === 'Confirmed');
        break;
      case 'home':
        result = result.filter(b => b.collection.type === 'Home Collection');
        break;
      case 'today':
        // Mock: show bookings from "today" — in production this checks real dates
        result = result.filter(b => b.status !== 'Completed' && b.status !== 'Cancelled');
        break;
      default:
        break;
    }

    // Search filtering
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase().trim();
      result = result.filter(b => 
        b.id.toLowerCase().includes(q) ||
        b.patient.name.toLowerCase().includes(q) ||
        b.patient.phone.includes(q)
      );
    }

    return result;
  }, [activeTab, searchQuery]);

  // Pagination calculations
  const totalItems = filteredBookings.length;
  const totalPages = Math.max(1, Math.ceil(totalItems / itemsPerPage));
  const paginatedData = filteredBookings.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

  // Reset page when filters change
  useEffect(() => {
    setCurrentPage(1);
  }, [activeTab, searchQuery]);

  // Cancel booking handler
  const handleCancelBooking = useCallback((booking: Booking) => {
    setCancelTarget(booking);
  }, []);

  const confirmCancelBooking = useCallback(() => {
    if (cancelTarget) {
      // Frontend-only state update — in production this calls an API
      success('Booking cancelled', `${cancelTarget.id} has been cancelled successfully`);
      setCancelTarget(null);
      closeDrawer();
    }
  }, [cancelTarget, success, closeDrawer]);

  // Status update handler
  const handleStatusUpdate = useCallback((booking: Booking, newStatus: BookingStatus) => {
    // Frontend-only — in production this calls an API
    success('Status updated', `${booking.id} has been updated to ${newStatus}`);
  }, [success]);

  const kpiSection = (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-5">
      <KPICard 
        title="Total Bookings" 
        value="1,248" 
        icon="calendar"
        trend={{ value: 12.5, isPositive: true, label: 'vs last 30 days' }}
        iconBgColor="bg-red-50"
        iconColor="text-red-500"
      />
      <KPICard 
        title="Pending" 
        value="86" 
        icon="clock"
        trend={{ value: 8, isPositive: false, label: 'Needs attention' }}
        iconBgColor="bg-amber-50"
        iconColor="text-amber-500"
      />
      <KPICard 
        title="Home Collections" 
        value="712" 
        icon="mapPin"
        trend={{ value: 57, isPositive: true, label: 'of total' }}
        iconBgColor="bg-blue-50"
        iconColor="text-blue-500"
      />
      <KPICard 
        title="Revenue Today" 
        value="₹45,780" 
        icon="creditCard"
        trend={{ value: 8.2, isPositive: true, label: 'vs yesterday' }}
        iconBgColor="bg-emerald-50"
        iconColor="text-emerald-500"
      />
    </div>
  );

  const toolbar = (
    <BookingsFilterBar
      activeTab={activeTab}
      onTabChange={setActiveTab}
      searchQuery={searchQuery}
      onSearchChange={setSearchQuery}
    />
  );

  return (
    <>
      <AdminPageTemplate
        kpiSection={kpiSection}
        toolbar={toolbar}
      >
        <BookingsTable 
          data={paginatedData} 
          isLoading={isLoading} 
          onRowClick={(booking) => openDrawer(booking.id)} 
          onCancelBooking={handleCancelBooking}
          pagination={{
            currentPage,
            totalPages,
            totalItems,
            itemsPerPage,
            onPageChange: setCurrentPage,
            onItemsPerPageChange: (items: number) => {
              setItemsPerPage(items);
              setCurrentPage(1);
            }
          }}
        />
      </AdminPageTemplate>

      <BookingDetailsDrawer 
        booking={selectedBooking}
        isOpen={isDrawerOpen}
        onClose={closeDrawer}
        onCancelBooking={handleCancelBooking}
        onStatusUpdate={handleStatusUpdate}
      />

      {/* Cancel Booking Confirmation Dialog */}
      <AdminDialog
        isOpen={cancelTarget !== null}
        onClose={() => setCancelTarget(null)}
        title="Cancel Booking"
        description={cancelTarget ? `Are you sure you want to cancel booking ${cancelTarget.id} for ${cancelTarget.patient.name}? This action cannot be undone.` : ''}
        size="sm"
        footer={
          <>
            <DialogFooterCancel onClose={() => setCancelTarget(null)} label="Keep Booking" />
            <DialogFooterConfirm onClick={confirmCancelBooking} label="Cancel Booking" variant="danger" />
          </>
        }
      />
    </>
  );
}

import Link from 'next/link';
import { Inter } from "next/font/google";

const inter = Inter({
  variable: "--font-inter",
  subsets: ["latin"],
  weight: ["400", "500", "600", "700", "800"],
});

export default function GlobalNotFound() {
  return (
    <html lang="en" className={`${inter.variable} h-full antialiased`}>
      <body className="min-h-full flex items-center justify-center bg-slate-50 p-4 font-sans">
        <div className="bg-white p-8 rounded-2xl shadow-xl text-center max-w-md w-full border border-slate-100">
          <h2 className="text-3xl font-bold text-slate-900 mb-3">404</h2>
          <h3 className="text-xl font-semibold text-slate-800 mb-2">Page Not Found</h3>
          <p className="text-slate-600 mb-6">
            The page you are looking for doesn't exist or has been moved.
          </p>
          <Link 
            href="/"
            className="inline-flex items-center justify-center px-6 py-2.5 bg-green-500 text-white font-medium rounded-lg hover:bg-green-600 transition-colors shadow-sm"
          >
            Return to Home
          </Link>
        </div>
      </body>
    </html>
  );
}

'use client';

import React, { useState } from 'react';
import { AdminDrawer } from '../overlays/AdminDrawer';
import { Booking, BookingStatus } from '@/data/admin/mockBookings';
import { StatusBadge } from '../feedback/StatusBadge';
import { Timeline } from '../feedback/Timeline';
import { AdminIcon } from '../navigation/AdminIcons';
import { AdminDropdown } from '../overlays/AdminDropdown';
import { AdminDialog, DialogFooterCancel, DialogFooterConfirm } from '../overlays/AdminDialog';
import { getStatusBadgeType } from '@/lib/admin/bookingUtils';

interface BookingDetailsDrawerProps {
  booking: Booking | null;
  isOpen: boolean;
  onClose: () => void;
  onCancelBooking?: (booking: Booking) => void;
  onStatusUpdate?: (booking: Booking, newStatus: BookingStatus) => void;
}

const STATUS_TRANSITIONS: Record<BookingStatus, BookingStatus[]> = {
  'Pending': ['Confirmed', 'Cancelled'],
  'Confirmed': ['Assigned', 'Cancelled'],
  'Assigned': ['Sample Collected', 'Cancelled'],
  'Sample Collected': ['Processing'],
  'Processing': ['Completed'],
  'Completed': [],
  'Cancelled': [],
};

export function BookingDetailsDrawer({ booking, isOpen, onClose, onCancelBooking, onStatusUpdate }: BookingDetailsDrawerProps) {
  const [activeTab, setActiveTab] = useState<'overview' | 'timeline' | 'payment'>('overview');
  const [showStatusDialog, setShowStatusDialog] = useState(false);

  if (!booking) return null;

  const availableTransitions = STATUS_TRANSITIONS[booking.status] || [];

  return (
    <AdminDrawer
      isOpen={isOpen}
      onClose={onClose}
      title={`Booking ${booking.id}`}
      subtitle={`Created on ${booking.createdAt}`}
      width="lg"
    >
      <div className="bg-slate-50/50 flex flex-col min-h-full">

        {/* Header Profile Section */}
        <div className="p-8 bg-white border-b border-slate-200/80 shrink-0">
          <div className="flex items-start justify-between mb-6">
            <div className="flex items-center gap-5">
              <div className="w-16 h-16 rounded-full bg-slate-100 flex items-center justify-center">
                <span className="text-xl font-bold text-slate-500">{booking.patient.name.charAt(0)}</span>
              </div>
              <div>
                <h3 className="text-[22px] font-bold text-slate-900 tracking-tight">{booking.patient.name}</h3>
                <div className="flex items-center gap-3 text-[13px] text-slate-500 mt-1 font-medium">
                  <span>{booking.patient.gender}, {booking.patient.age} yrs</span>
                  <span className="w-1 h-1 rounded-full bg-slate-300"></span>
                  <span>{booking.patient.phone}</span>
                </div>
              </div>
            </div>
            <StatusBadge type={getStatusBadgeType(booking.status)} status={booking.status} />
          </div>

          {/* Quick Actions */}
          <div className="flex items-center gap-3">
            <button
              onClick={() => setShowStatusDialog(true)}
              disabled={availableTransitions.length === 0}
              className="flex-1 bg-slate-900 text-white py-2 px-4 rounded-md text-[13px] font-semibold hover:bg-slate-800 transition-colors shadow-sm disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Update Status
            </button>
            <button className="flex-1 bg-white border border-slate-200 text-slate-700 py-2 px-4 rounded-md text-[13px] font-semibold hover:bg-slate-50 transition-colors shadow-sm">
              View Report
            </button>
            <AdminDropdown
              align="right"
              trigger={
                <button className="p-2 border border-slate-200 text-slate-400 rounded-md hover:bg-slate-50 hover:text-slate-600 transition-colors shadow-sm" aria-label="More booking actions">
                  <AdminIcon name="moreVertical" className="w-[18px] h-[18px]" strokeWidth={2} />
                </button>
              }
              items={[
                { label: 'Edit Booking', icon: 'edit', onClick: () => console.log('Edit', booking.id) },
                { label: 'Reschedule', icon: 'calendar', onClick: () => console.log('Reschedule', booking.id) },
                ...(booking.status !== 'Cancelled' && booking.status !== 'Completed' ? [
                  { label: 'Cancel Booking', icon: 'x' as const, danger: true, onClick: () => onCancelBooking?.(booking) }
                ] : [])
              ]}
            />
          </div>
        </div>

        {/* Navigation Tabs */}
        <div className="px-8 border-b border-slate-200/80 bg-white shrink-0">
          <nav className="flex space-x-8 -mb-px">
            {(['overview', 'timeline', 'payment'] as const).map((tab) => (
              <button
                key={tab}
                onClick={() => setActiveTab(tab)}
                className={`py-4 text-[13px] font-semibold border-b-[3px] transition-colors capitalize ${
                  activeTab === tab
                    ? 'border-slate-900 text-slate-900'
                    : 'border-transparent text-slate-500 hover:text-slate-700 hover:border-slate-300'
                }`}
              >
                {tab}
              </button>
            ))}
          </nav>
        </div>

        {/* Tab Content */}
        <div className="p-8 flex-1">
          {activeTab === 'overview' && (
            <div className="space-y-6">
              {/* Collection Details */}
              <div className="bg-white rounded-lg border border-slate-200/80 p-5 shadow-[0_1px_2px_rgba(0,0,0,0.01)]">
                <h4 className="text-xs font-bold text-slate-400 mb-4 uppercase tracking-wider">Collection Details</h4>
                <div className="grid grid-cols-2 gap-y-5 gap-x-8">
                  <div>
                    <p className="text-[12px] text-slate-500 mb-1 font-medium">Type</p>
                    <p className="text-[13px] font-semibold text-slate-900 flex items-center gap-2">
                      <AdminIcon name={booking.collection.type === 'Home Collection' ? 'mapPin' : 'testTube'} className="w-3.5 h-3.5 text-slate-400" strokeWidth={2.5} />
                      {booking.collection.type}
                    </p>
                  </div>
                  <div>
                    <p className="text-[12px] text-slate-500 mb-1 font-medium">Date & Time</p>
                    <p className="text-[13px] font-semibold text-slate-900">{booking.collection.date}, {booking.collection.timeSlot}</p>
                  </div>
                  {booking.collection.address && (
                    <div className="col-span-2 pt-4 border-t border-slate-100">
                      <p className="text-[12px] text-slate-500 mb-1 font-medium">Collection Address</p>
                      <p className="text-[13px] font-medium text-slate-900 leading-relaxed">{booking.collection.address}</p>
                    </div>
                  )}
                  {booking.collection.assignedPhlebotomist && (
                    <div className="col-span-2 pt-4 border-t border-slate-100 flex items-center justify-between">
                      <div>
                        <p className="text-[12px] text-slate-500 mb-1 font-medium">Assigned To</p>
                        <p className="text-[13px] font-semibold text-slate-900">{booking.collection.assignedPhlebotomist}</p>
                      </div>
                      <button className="text-[12px] text-slate-500 font-semibold hover:text-slate-900 transition-colors">Reassign</button>
                    </div>
                  )}
                </div>
              </div>

              {/* Tests & Packages */}
              <div className="bg-white rounded-lg border border-slate-200/80 overflow-hidden shadow-[0_1px_2px_rgba(0,0,0,0.01)]">
                <div className="p-4 border-b border-slate-200/80 bg-slate-50/50">
                  <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Requested Tests</h4>
                </div>
                <ul className="divide-y divide-slate-100">
                  {booking.items.map((item, idx) => (
                    <li key={idx} className="p-4 flex items-center justify-between">
                      <div className="flex items-start gap-3">
                        <div className="mt-0.5">
                          <AdminIcon name={item.type === 'Package' ? 'package' : 'testTube'} className="w-[18px] h-[18px] text-slate-400" strokeWidth={2} />
                        </div>
                        <div>
                          <p className="text-[13px] font-semibold text-slate-900">{item.name}</p>
                          <p className="text-[12px] text-slate-500 font-medium">{item.type}</p>
                        </div>
                      </div>
                      <p className="text-[13px] font-semibold text-slate-900 tabular-nums">₹{item.price}</p>
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          )}

          {activeTab === 'timeline' && (
            <div className="bg-white rounded-lg border border-slate-200/80 p-6 shadow-[0_1px_2px_rgba(0,0,0,0.01)]">
              <h4 className="text-xs font-bold text-slate-400 mb-6 uppercase tracking-wider">Workflow Activity</h4>
              <Timeline events={booking.timeline} />
            </div>
          )}

          {activeTab === 'payment' && (
            <div className="bg-white rounded-lg border border-slate-200/80 p-6 shadow-[0_1px_2px_rgba(0,0,0,0.01)]">
              <div className="flex items-center justify-between mb-6">
                <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider">Payment Summary</h4>
                <StatusBadge 
                  type={booking.payment.status === 'Paid' ? 'success' : booking.payment.status === 'Failed' ? 'danger' : 'warning'} 
                  status={booking.payment.status} 
                />
              </div>
              <div className="space-y-4">
                <div className="flex justify-between text-[13px]">
                  <span className="text-slate-500 font-medium">Subtotal</span>
                  <span className="text-slate-900 font-semibold tabular-nums">₹{booking.payment.total}</span>
                </div>
                <div className="flex justify-between text-[13px]">
                  <span className="text-slate-500 font-medium">Taxes</span>
                  <span className="text-slate-900 font-semibold tabular-nums">₹0</span>
                </div>
                <div className="flex justify-between text-[13px]">
                  <span className="text-slate-500 font-medium">Discount</span>
                  <span className="text-emerald-600 font-semibold tabular-nums">-₹0</span>
                </div>
                <div className="pt-4 border-t border-slate-100 flex justify-between">
                  <span className="font-bold text-slate-900 text-[14px]">Total Amount</span>
                  <span className="font-bold text-[18px] text-slate-900 tabular-nums leading-none">₹{booking.payment.total.toLocaleString('en-IN')}</span>
                </div>
              </div>

              <div className="mt-8 p-4 bg-slate-50 rounded-md border border-slate-200/80 flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <div className="w-8 h-8 rounded-full bg-white border border-slate-200 flex items-center justify-center">
                    <AdminIcon name="creditCard" className="w-4 h-4 text-slate-500" strokeWidth={2} />
                  </div>
                  <div>
                    <p className="text-[13px] font-semibold text-slate-900">Payment Method</p>
                    <p className="text-[12px] text-slate-500 font-medium">{booking.payment.method}</p>
                  </div>
                </div>
                {booking.payment.status === 'Paid' && (
                  <button className="text-[12px] font-semibold text-slate-500 hover:text-slate-900 transition-colors">
                    Download Receipt
                  </button>
                )}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Update Status Dialog */}
      <AdminDialog
        isOpen={showStatusDialog}
        onClose={() => setShowStatusDialog(false)}
        title="Update Booking Status"
        description={`Select the next status for booking ${booking.id}`}
        size="sm"
        footer={
          <DialogFooterCancel onClose={() => setShowStatusDialog(false)} />
        }
      >
        <div className="flex flex-col gap-2">
          {availableTransitions.map((status) => (
            <button
              key={status}
              onClick={() => {
                onStatusUpdate?.(booking, status);
                setShowStatusDialog(false);
              }}
              className="flex items-center gap-3 w-full p-3 rounded-md border border-slate-200 hover:bg-slate-50 hover:border-slate-300 transition-colors text-left"
            >
              <StatusBadge type={getStatusBadgeType(status)} status={status} />
              <span className="text-[13px] text-slate-500 ml-auto">→</span>
            </button>
          ))}
          {availableTransitions.length === 0 && (
            <p className="text-[13px] text-slate-500 text-center py-4">This booking has reached its final status.</p>
          )}
        </div>
      </AdminDialog>
    </AdminDrawer>
  );
}

'use client';

import React, { useMemo } from 'react';
import { ConfigurableDataTable, ColumnDef, ConfigurableDataTableProps } from '../tables/DataTable';
import { Booking } from '@/data/admin/mockBookings';
import { StatusBadge } from '../feedback/StatusBadge';
import { AdminDropdown } from '../overlays/AdminDropdown';
import { AdminIcon } from '../navigation/AdminIcons';
import { getStatusBadgeType } from '@/lib/admin/bookingUtils';

interface BookingsTableProps {
  data: Booking[];
  isLoading?: boolean;
  onRowClick: (booking: Booking) => void;
  onCancelBooking?: (booking: Booking) => void;
  pagination?: ConfigurableDataTableProps<Booking>['pagination'];
}



export function BookingsTable({ data, isLoading, onRowClick, onCancelBooking, pagination }: BookingsTableProps) {

  const columns = useMemo<ColumnDef<Booking>[]>(() => [
    {
      id: 'id',
      header: 'Booking ID',
      accessorKey: 'id',
      cellClassName: 'font-medium text-[var(--admin-primary)]',
    },
    {
      id: 'patient',
      header: 'Patient',
      cell: ({ row }) => (
        <div className="relative group/patient">
          <div className="font-semibold text-slate-900 text-[13px] tracking-tight flex items-center gap-1.5">
            {row.patient.name}
            <button 
              className="opacity-0 group-hover/patient:opacity-100 p-0.5 text-slate-400 hover:text-slate-700 transition-opacity"
              onClick={(e) => {
                e.stopPropagation();
                navigator.clipboard.writeText(row.patient.name);
              }}
              title="Copy name"
            >
              <AdminIcon name="copy" className="w-3 h-3" strokeWidth={2.5} />
            </button>
          </div>
          <div className="text-[12px] text-slate-500 mt-0.5 flex items-center gap-1.5">
            {row.patient.phone}
            <button 
              className="opacity-0 group-hover/patient:opacity-100 p-0.5 text-slate-400 hover:text-slate-700 transition-opacity"
              onClick={(e) => {
                e.stopPropagation();
                navigator.clipboard.writeText(row.patient.phone);
              }}
              title="Copy phone"
            >
              <AdminIcon name="copy" className="w-3 h-3" strokeWidth={2.5} />
            </button>
          </div>
        </div>
      )
    },
    {
      id: 'date',
      header: 'Date & Time',
      cell: ({ row }) => (
        <div>
          <div className="text-[13px] font-medium text-slate-900 whitespace-nowrap">{row.collection.date}</div>
          <div className="text-[12px] text-slate-500 mt-0.5 whitespace-nowrap">{row.collection.timeSlot}</div>
        </div>
      )
    },
    {
      id: 'type',
      header: 'Type',
      cell: ({ row }) => (
        <div className="flex items-center gap-2 text-slate-600">
          <AdminIcon 
            name={row.collection.type === 'Home Collection' ? 'mapPin' : 'testTube'} 
            className="w-[14px] h-[14px] shrink-0 text-slate-400" 
            strokeWidth={2}
          />
          <span className="whitespace-nowrap text-[13px] font-medium">{row.collection.type}</span>
        </div>
      )
    },
    {
      id: 'status',
      header: 'Status',
      cell: ({ row }) => (
        <StatusBadge 
          type={getStatusBadgeType(row.status)} 
          status={row.status} 
        />
      )
    },
    {
      id: 'payment',
      header: 'Amount',
      cellClassName: 'text-right font-semibold text-slate-900 text-[13px] tabular-nums',
      cell: ({ row }) => (
        <span className="flex items-center justify-end">
          <span className="text-slate-400 font-normal mr-0.5">₹</span>
          {row.payment.total.toLocaleString('en-IN')}
        </span>
      )
    },
    {
      id: 'actions',
      header: '',
      cellClassName: 'w-32 text-right',
      cell: ({ row }) => (
        <div className="flex items-center justify-end gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
          <button 
            className="p-1.5 text-slate-400 hover:text-slate-900 hover:bg-slate-100 rounded-md transition-colors" 
            onClick={(e) => e.stopPropagation()}
            title="Edit Booking"
            aria-label={`Edit booking ${row.id}`}
          >
            <AdminIcon name="edit" className="w-[16px] h-[16px]" strokeWidth={2} />
          </button>
          <button 
            className="p-1.5 text-slate-400 hover:text-slate-900 hover:bg-slate-100 rounded-md transition-colors" 
            onClick={(e) => e.stopPropagation()}
            title="Message Patient"
            aria-label={`Message ${row.patient.name}`}
          >
            <AdminIcon name="messageSquare" className="w-[16px] h-[16px]" strokeWidth={2} />
          </button>
          <AdminDropdown 
            align="right"
            trigger={
              <button className="p-1.5 text-slate-400 hover:text-slate-900 hover:bg-slate-100 rounded-md transition-colors" onClick={(e) => e.stopPropagation()} aria-label={`More actions for ${row.id}`}>
                <AdminIcon name="moreVertical" className="w-[18px] h-[18px]" strokeWidth={2} />
              </button>
            }
          items={[
            { label: 'View Details', icon: 'eye', onClick: () => onRowClick(row) },
            { label: 'Edit Booking', icon: 'edit', onClick: () => console.log('Edit', row.id) },
            { label: 'Cancel Booking', icon: 'x', danger: true, onClick: () => onCancelBooking?.(row) }
          ]}
          />
        </div>
      )
    }
  ], [onRowClick]);

  return (
    <ConfigurableDataTable 
      data={data}
      columns={columns}
      keyExtractor={(row) => row.id}
      onRowClick={onRowClick}
      isLoading={isLoading}
      pagination={pagination}
    />
  );
}

'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { adminNavigation } from '@/config/adminNavigation';
import { AdminIcon, AdminIconName } from './AdminIcons';
import { useAuth } from '@/context/AuthContext';
import { hasPermission, Role } from '@/lib/auth/permissions';

export function AdminSidebar() {
  const pathname = usePathname();
  const { user } = useAuth();
  // Assume user object has a 'role' property. Fallback to 'admin' for UI dev if not present.
  const userRole = (user as any)?.role || 'admin';

  const [isCollapsed, setIsCollapsed] = useState(false);

  return (
    <div 
      style={{ width: isCollapsed ? 80 : 230, flexShrink: 0, position: 'relative', display: 'flex' }}
      className={`bg-slate-900 border-r border-white/5 flex-col transition-all duration-400 ease-[cubic-bezier(0.2,0.8,0.2,1)] h-full z-30`}
    >
      <div className="h-[80px] flex items-center px-6 justify-between shrink-0 mb-4 mt-2">
        {!isCollapsed && (
          <Link href="/admin" className="flex items-center gap-3 !text-white hover:opacity-80 transition-opacity">
            <div className="w-8 h-8 bg-gradient-to-br from-[#e31837] to-[#b9112a] rounded-[10px] flex items-center justify-center shrink-0 shadow-lg shadow-red-900/20">
              <span className="text-white font-bold text-lg leading-none">A</span>
            </div>
            <span className="font-bold text-[18px] tracking-tight whitespace-nowrap">AGAM Admin</span>
          </Link>
        )}
        <button 
          onClick={() => setIsCollapsed(!isCollapsed)}
          className={`p-2 rounded-xl hover:bg-white/10 text-slate-400 hover:text-white transition-all duration-300 ${isCollapsed ? 'mx-auto' : ''}`}
          title={isCollapsed ? "Expand sidebar" : "Collapse sidebar"}
        >
          <AdminIcon name="menu" className="w-5 h-5" />
        </button>
      </div>

      <div className="flex-1 overflow-y-auto px-3 custom-scrollbar flex flex-col gap-4 pb-8">
        {adminNavigation.map((group) => {
          const visibleItems = group.items.filter(item => hasPermission(userRole as Role, item.roles));
          if (visibleItems.length === 0) return null;

          return (
            <div key={group.title} className="px-1">
              {!isCollapsed && (
                <div className="px-2 mb-2 text-xs font-bold uppercase tracking-[0.1em] !text-slate-400">
                  {group.title}
                </div>
              )}
              <ul className="space-y-1">
                {visibleItems.map((item) => {
                  const isActive = item.href === '/admin' 
                    ? pathname === '/admin' 
                    : pathname === item.href || pathname.startsWith(`${item.href}/`);
                  return (
                    <li key={item.title}>
                      <Link 
                        href={item.href}
                        className={`relative flex items-center gap-2.5 px-2 h-[40px] rounded-[8px] transition-all duration-300 group overflow-hidden ${
                          isActive 
                            ? 'bg-white/10 !text-white font-medium' 
                            : '!text-slate-300 hover:bg-white/5 hover:!text-white font-medium'
                        } ${isCollapsed ? 'justify-center' : ''}`}
                        title={isCollapsed ? item.title : undefined}
                      >
                        {isActive && (
                          <div className={`absolute left-0 top-1/2 -translate-y-1/2 w-[3px] h-6 bg-[#e31837] rounded-r-full shadow-[0_0_10px_rgba(227,24,55,0.5)] ${isCollapsed ? 'left-0' : ''}`} />
                        )}
                        <AdminIcon 
                          name={item.icon as AdminIconName} 
                          className={`w-[18px] h-[18px] shrink-0 transition-transform duration-300 group-hover:scale-110 ${isActive ? '!text-[#e31837]' : '!text-slate-400 group-hover:!text-white'}`} 
                          strokeWidth={2}
                        />
                        {!isCollapsed && (
                          <span className={`text-[14px] transition-transform duration-300 ${isActive ? '!text-white translate-x-1' : 'group-hover:translate-x-1'}`}>{item.title}</span>
                        )}
                      </Link>
                    </li>
                  );
                })}
              </ul>
            </div>
          );
        })}
      </div>

      <div className="p-4 mt-auto border-t border-white/5">
        <div className={`bg-transparent rounded-xl hover:bg-white/5 transition-colors cursor-pointer flex items-center justify-between group ${isCollapsed ? 'justify-center p-2' : 'p-3'}`}>
          <div className="flex items-center gap-3 overflow-hidden">
            <div className="w-10 h-10 rounded-full bg-gradient-to-br from-slate-700 to-slate-800 border border-white/10 flex items-center justify-center shrink-0 shadow-lg group-hover:scale-105 transition-transform duration-300">
              <span className="text-white text-[14px] font-bold leading-none">
                {user?.fullName ? user.fullName.charAt(0).toUpperCase() : 'A'}
              </span>
            </div>
            {!isCollapsed && (
              <div className="overflow-hidden">
                <div className="text-[13px] font-semibold !text-white truncate leading-tight">
                  {user?.fullName || 'Admin User'}
                </div>
                <div className="text-xs !text-white/50 truncate capitalize mt-0.5 group-hover:!text-white/70 transition-colors">
                  {userRole === 'admin' ? 'Super Admin' : userRole}
                </div>
              </div>
            )}
          </div>
          {!isCollapsed && (
            <AdminIcon name="chevronDown" className="w-4 h-4 text-white/30 group-hover:text-white/70 shrink-0 transition-colors" />
          )}
        </div>
      </div>
    </div>
  );
}

